            DateTime customDateTime = new DateTime(2021, 6, 6, 13, 13, 13);
            systemTime.Set(customDateTime);
            TimeLoggerUsingSystemTime timeLogger = new TimeLoggerUsingSystemTime(systemTime);

            //// Act
