using System.Collections.Generic;

namespace TemplateMethodPattern
{
    class Program
    {
        static void Main(string[] args)
        {
            var dish = new ChineseDish("辣炒牛肉空心菜");

            dish.Prepare();
            dish.Cook();
            dish.SetDish();
            dish.Done();
        }
    }
}
{% endcodeblock %}

