## Visitor 模式

現在有兩種交通工具；機車和巴士，假設乘客只在意三個項目：馬力、限乘人數、有沒有冷氣．將這三個屬性定義在介面，另外還需定義一個方法 `Accept`，使機車和巴士類別能夠讓 Visitor 訪問。

{% codeblock lang:cs %}
/*IVisitor.cs*/

namespace DemoCode.DesignPattern.Visitor.OriginVisitor
{
    /// <summary>
    /// IVisitor
    /// </summary>
    public interface IVisitor
    {
        /// <summary>
        /// Visit for Motor
        /// </summary>
        /// <param name="motor"></param>
        void Visit(Motor motor);

        /// <summary>
        /// Visit for Bus
        /// </summary>
        /// <param name="bus"></param>
        void Visit(Bus bus);
    }
}
{% endcodeblock %}

{% codeblock lang:cs %}
/*ITransportation.cs*/

namespace DemoCode.DesignPattern.Visitor.OriginVisitor
{
    /// <summary>
    /// 交通工具
    /// </summary>
    public interface ITransportation
    {
        /// <summary>
        /// 馬力
        /// </summary>
        decimal Power { get; set; }

        /// <summary>
        /// 限乘人數
        /// </summary>
        int NumberOfPassenger { get; set; }

        /// <summary>
        /// 是否有冷氣
        /// </summary>
        bool HasAirConditioner { get; set; }

        /// <summary>
        /// Accept
        /// </summary>
        /// <param name="visitor"></param>
        void Accept(IVisitor visitor);
    }
}
{% endcodeblock %}

{% codeblock lang:cs %}
/*Motor.cs*/

namespace DemoCode.DesignPattern.Visitor.OriginVisitor
{
    /// <summary>
    /// 機車
    /// </summary>
    public class Motor : ITransportation
    {
        /// <summary>
        /// 馬力
        /// </summary>
        public decimal Power { get; set; }

        /// <summary>
        /// 限乘人數
        /// </summary>
        public int NumberOfPassenger { get; set; }

        /// <summary>
        /// 是否有冷氣
        /// </summary>
        public bool HasAirConditioner { get; set; }

        /// <summary>
        /// 建構子
        /// </summary>
        /// <param name="power"></param>
        /// <param name="numberOfPassenger"></param>
        /// <param name="hasAirConditioner"></param>
        public Motor(decimal power, int numberOfPassenger, bool hasAirConditioner)
        {
            this.Power = power;
            this.NumberOfPassenger = numberOfPassenger;
            this.HasAirConditioner = hasAirConditioner;
        }

        /// <summary>
        /// Accept
        /// </summary>
        /// <param name="visitor"></param>
        public void Accept(IVisitor visitor)
        {
            visitor.Visit(this);
        }
    }
}
{% endcodeblock %}

{% codeblock lang:cs %}
/*Bus.cs*/

namespace DemoCode.DesignPattern.Visitor.OriginVisitor
{
    /// <summary>
    /// 巴士
    /// </summary>
    public class Bus : ITransportation
    {
        /// <summary>
        /// 馬力
        /// </summary>
        public decimal Power { get; set; }

        /// <summary>
        /// 限乘人數
        /// </summary>
        public int NumberOfPassenger { get; set; }

        /// <summary>
        /// 是否有冷氣
        /// </summary>
        public bool HasAirConditioner { get; set; }

        /// <summary>
        /// 建構子
        /// </summary>
        /// <param name="power"></param>
        /// <param name="numberOfPassenger"></param>
        /// <param name="hasAirConditioner"></param>
        public Bus(decimal power, int numberOfPassenger, bool hasAirConditioner)
        {
            this.Power = power;
            this.NumberOfPassenger = numberOfPassenger;
            this.HasAirConditioner = hasAirConditioner;
        }

        /// <summary>
        /// Accept
        /// </summary>
        /// <param name="visitor"></param>
        public void Accept(IVisitor visitor)
        {
            visitor.Visit(this);
        }
    }
}
{% endcodeblock %}

